#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.1 Pro Terminal - Complete All-in-One Installer
# Streamlined & Faster UI:
#   - Removed Linear & TV Pro themes for lighter, cleaner code
#   - 2 Structural Layouts sharing unified Obsidian Gold Pro palette:
#       1) Obsidian Gold Pro (Collapsible Left Sidebar + Horizontal Telemetry)
#       2) Bento HUD Studio  (Floating Bottom Gold Dock + 4-Pod Radial HUD)
#   - Clean Overview Hierarchy + Dedicated Full-Screen Live Console Tab
#   - Global Position Direction Mode (Smart Auto / LONG Only / SHORT Only)
#   - Dedicated Backup Bot Token + kaviancrypto v4.2 Default Strategy
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v7.1 Pro - All-in-One Installer & Upgrade"
echo "  Streamlined Obsidian Gold + Bento HUD + Live Console"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_1.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_1.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_1.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.1 core files ==="
