    echo "Seeded custom_strategy.py (kaviancrypto v4.2 Smart Auto Pro + 15M SMC Sniper)."
else
    echo "Existing custom_strategy.py preserved."
fi

echo "=== [4/6] Setting up Python venv & installing dependencies ==="
if [ ! -d "$APP_DIR/venv" ]; then
    python3 -m venv "$APP_DIR/venv"
fi
"$APP_DIR/venv/bin/pip" install --upgrade pip
"$APP_DIR/venv/bin/pip" install flask requests pandas numpy matplotlib pysocks apscheduler gunicorn websocket-client werkzeug

echo "=== [5/6] Verifying Python syntax & import health ==="
"$APP_DIR/venv/bin/python" -m py_compile "$APP_DIR/strategy_manager.py" "$APP_DIR/scanner.py" "$APP_DIR/app.py" "$APP_DIR/custom_strategy.py"
KAVIAN_DISABLE_SCHEDULER=1 "$APP_DIR/venv/bin/python" -c "import sys; sys.path.insert(0, '/opt/kaviancrypto'); import strategy_manager, scanner, app; print('IMPORT_SELF_TEST_OK')"

echo "=== [6/6] Configuring systemd service & firewall (Port $PORT) ==="
cat << EOF_SERVICE > /etc/systemd/system/kaviancrypto.service
[Unit]
Description=kaviancrypto v7.1 Pro Terminal & Multi-Market Scanner
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=root
WorkingDirectory=$APP_DIR
ExecStart=$APP_DIR/venv/bin/gunicorn -w 1 --threads 4 --timeout 180 -b 0.0.0.0:$PORT app:app
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF_SERVICE

systemctl daemon-reload
systemctl enable kaviancrypto.service
systemctl restart kaviancrypto.service
sleep 2

if command -v ufw >/dev/null 2>&1; then
    ufw allow $PORT/tcp || true
fi

STATUS=$(systemctl is-active kaviancrypto.service || true)
SERVER_IP=$(curl -s --max-time 5 https://api.ipify.org || hostname -I | awk '{print $1}')

echo ""
echo "========================================================"
echo "  kaviancrypto v7.1 Pro Installation / Upgrade Complete!"
echo "  Service   : $STATUS"
echo "  Panel URL : http://$SERVER_IP:$PORT"
echo "  Default   : admin / admin (existing config preserved)"
echo "========================================================"
